class Solution {
public:
    int paintWalls(vector<int>& cost, vector<int>& time) {
        int n = cost.size();
        vector<int> dp(n + 1, 1e9);
        dp[0] = 0;
        for (int i = 0; i < n; ++i) {
            int c = cost[i], gain = 1 + time[i];
            for (int j = n; j >= 0; --j) {
                dp[j] = min(dp[j], c + dp[max(0, j - gain)]);
            }
        }
        return dp[n];
    }
};

class Solution {
    public int paintWalls(int[] cost, int[] time) {
        int n = cost.length;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, (int)1e9);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            int c = cost[i], gain = 1 + time[i];
            for (int j = n; j >= 0; j--) {
                dp[j] = Math.min(dp[j], c + dp[Math.max(0, j - gain)]);
            }
        }
        return dp[n];
    }
}

var paintWalls = function(cost, time) {
    const n = cost.length;
    const dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 0; i < n; i++) {
        const c = cost[i], gain = 1 + time[i];
        for (let j = n; j >= 0; j--) {
            dp[j] = Math.min(dp[j], c + dp[Math.max(0, j - gain)]);
        }
    }
    return dp[n];
};
